        endpoints.MapPost("/api/v1/sales/customer-returns/{returnId:guid}/reject", async (Guid returnId, SalesCustomerReturnActionRequest? request, HttpContext http, ITrustedRequestContextResolver resolver, ProcurementTenantContextResolver tenant, SalesCustomerReturnService service) => await ExecuteMutationAsync(http, resolver, tenant, "sales.customer-return.reject", returnId, (context, version, _) => service.MutateAsync(context, returnId, version!, SalesCustomerReturnMutation.Reject, request?.Reason, Key(http), http.RequestAborted))).WithName("sales.customer-return.reject").WithMetadata(Metadata("sales.customer-return.reject"));
        endpoints.MapPost("/api/v1/sales/customer-returns/{returnId:guid}/cancel", async (Guid returnId, SalesCustomerReturnActionRequest? request, HttpContext http, ITrustedRequestContextResolver resolver, ProcurementTenantContextResolver tenant, SalesCustomerReturnService service) => await ExecuteMutationAsync(http, resolver, tenant, "sales.customer-return.cancel", returnId, (context, version, _) => service.MutateAsync(context, returnId, version!, SalesCustomerReturnMutation.Cancel, request?.Reason, Key(http), http.RequestAborted))).WithName("sales.customer-return.cancel").WithMetadata(Metadata("sales.customer-return.cancel"));
        endpoints.MapPost("/api/v1/sales/customer-returns/{returnId:guid}/reverse", async (Guid returnId, SalesCustomerReturnActionRequest? request, HttpContext http, ITrustedRequestContextResolver resolver, ProcurementTenantContextResolver tenant, SalesCustomerReturnService service) => await ExecuteMutationAsync(http, resolver, tenant, "sales.customer-return.reverse", returnId, (context, version, _) => service.MutateAsync(context, returnId, version!, SalesCustomerReturnMutation.Reverse, request?.Reason, Key(http), http.RequestAborted))).WithName("sales.customer-return.reverse").WithMetadata(Metadata("sales.customer-return.reverse"));
        endpoints.MapGet("/api/v1/sales/customer-returns/{returnId:guid}/history", async (Guid returnId, HttpContext http, ITrustedRequestContextResolver resolver, ProcurementTenantContextResolver tenant, SalesCustomerReturnService service) =>
