        endpoints.MapPost("/api/v1/inventory/customer-returns/{salesCustomerReturnId:guid}/inspect", async (Guid salesCustomerReturnId, InventoryCustomerReturnInspectionRequest? request, HttpContext http, ITrustedRequestContextResolver resolver, InventoryTenantContextResolver tenant, InventoryCustomerReturnService service) =>
            request is null ? Problem(400, "validation_failed", "inventory.customer-return.inspect") : await ExecuteMutationAsync(http, resolver, tenant, "inventory.customer-return.inspect", true, (context, version) => service.InspectAsync(context, salesCustomerReturnId, version!, request, Key(http), http.RequestAborted))).WithName("inventory.customer-return.inspect").WithMetadata(Metadata("inventory.customer-return.inspect"));
        endpoints.MapPost("/api/v1/inventory/customer-returns/{salesCustomerReturnId:guid}/reverse", async (Guid salesCustomerReturnId, HttpContext http, ITrustedRequestContextResolver resolver, InventoryTenantContextResolver tenant, InventoryCustomerReturnService service) =>
