        endpoints.MapPost("/api/v1/finance/credit-notes", async (FinanceCreditNoteCreateRequest? request, HttpContext http, ITrustedRequestContextResolver resolver, FinanceCustomerReturnService service) =>
            request is null ? Problem(400, "validation_failed", "finance.credit-note.create") : await ExecuteMutationAsync(http, resolver, "finance.credit-note.create", false, (context, version) => service.CreateAsync(context, request, Key(http), http.RequestAborted))).WithName("finance.credit-note.create").WithMetadata(Metadata("finance.credit-note.create"));
        endpoints.MapPost("/api/v1/finance/credit-notes/{creditNoteId:guid}/submit", async (Guid creditNoteId, FinanceCreditNoteActionRequest? request, HttpContext http, ITrustedRequestContextResolver resolver, FinanceCustomerReturnService service) => await ExecuteMutationAsync(http, resolver, "finance.credit-note.submit", true, (context, version) => service.MutateAsync(context, creditNoteId, version!, FinanceCreditNoteMutation.Submit, request?.Reason, Key(http), http.RequestAborted))).WithName("finance.credit-note.submit").WithMetadata(Metadata("finance.credit-note.submit"));
        endpoints.MapPost("/api/v1/finance/credit-notes/{creditNoteId:guid}/approve", async (Guid creditNoteId, FinanceCreditNoteActionRequest? request, HttpContext http, ITrustedRequestContextResolver resolver, FinanceCustomerReturnService service) => await ExecuteMutationAsync(http, resolver, "finance.credit-note.approve", true, (context, version) => service.MutateAsync(context, creditNoteId, version!, FinanceCreditNoteMutation.Approve, request?.Reason, Key(http), http.RequestAborted))).WithName("finance.credit-note.approve").WithMetadata(Metadata("finance.credit-note.approve"));
        endpoints.MapPost("/api/v1/finance/credit-notes/{creditNoteId:guid}/reject", async (Guid creditNoteId, FinanceCreditNoteActionRequest? request, HttpContext http, ITrustedRequestContextResolver resolver, FinanceCustomerReturnService service) => await ExecuteMutationAsync(http, resolver, "finance.credit-note.reject", true, (context, version) => service.MutateAsync(context, creditNoteId, version!, FinanceCreditNoteMutation.Reject, request?.Reason, Key(http), http.RequestAborted))).WithName("finance.credit-note.reject").WithMetadata(Metadata("finance.credit-note.reject"));
        endpoints.MapPost("/api/v1/finance/credit-notes/{creditNoteId:guid}/cancel", async (Guid creditNoteId, FinanceCreditNoteActionRequest? request, HttpContext http, ITrustedRequestContextResolver resolver, FinanceCustomerReturnService service) => await ExecuteMutationAsync(http, resolver, "finance.credit-note.cancel", true, (context, version) => service.MutateAsync(context, creditNoteId, version!, FinanceCreditNoteMutation.Cancel, request?.Reason, Key(http), http.RequestAborted))).WithName("finance.credit-note.cancel").WithMetadata(Metadata("finance.credit-note.cancel"));
