    private static async Task<IResult> SalesRead<T>(HttpContext http, ITrustedRequestContextResolver resolver, ProcurementTenantContextResolver tenant, string operation, Func<ProcurementRequestContext, Task<SalesCustomerReturnOperationResult<T>>> action, Func<T, object?> map, bool etag = false)
    {
        var foundation = await resolver.ResolveAsync(http, http.RequestAborted); var resolved = tenant.Resolve(foundation);
        if (!resolved.Allowed || resolved.Context is null) return Problem(foundation.SecurityProfile == FoundationSecurityProfile.Anonymous ? 401 : 403, resolved.Code, operation);
        var result = await action(resolved.Context); if (!result.Succeeded || result.Value is null) return Problem(Status(result.Code), result.Code, operation);
        if (etag && result.Value is SalesCustomerReturnResponse value) SetEtag(http, value.Version);
        return Results.Ok(map(result.Value));
    }

    private static async Task<IResult> ExecuteMutationAsync<T>(HttpContext http, ITrustedRequestContextResolver resolver, ProcurementTenantContextResolver tenant, string operation, Guid? id, Func<ProcurementRequestContext, byte[]?, string?, Task<SalesCustomerReturnOperationResult<T>>> action)
    {
        if (!await Anti(http)) return Problem(403, "antiforgery_failed", operation); var key = Key(http); if (!FoundationCorrelation.IsValid(key)) return Problem(400, "idempotency_key_invalid", operation); var version = id is null ? null : ReadVersion(http); if (id is not null && version is null) return Problem(400, "version_required", operation);
        var foundation = await resolver.ResolveAsync(http, http.RequestAborted); var resolved = tenant.Resolve(foundation); if (!resolved.Allowed || resolved.Context is null) return Problem(foundation.SecurityProfile == FoundationSecurityProfile.Anonymous ? 401 : 403, resolved.Code, operation);
        var result = await action(resolved.Context, version, key); if (!result.Succeeded || result.Value is null) return Problem(Status(result.Code), result.Code, operation); if (result.Value is SalesCustomerReturnResponse value) SetEtag(http, value.Version); return Results.Ok(result.Value);
    }

    private static async Task<IResult> InventoryRead<T>(HttpContext http, ITrustedRequestContextResolver resolver, InventoryTenantContextResolver tenant, string operation, Func<InventoryRequestContext, Task<InventoryOperationResult<T>>> action, bool etag = false)
    {
        var foundation = await resolver.ResolveAsync(http, http.RequestAborted); var resolved = tenant.Resolve(foundation); if (!resolved.Allowed || resolved.Context is null) return Problem(foundation.SecurityProfile == FoundationSecurityProfile.Anonymous ? 401 : 403, resolved.Code, operation); var result = await action(resolved.Context); if (!result.Succeeded || result.Value is null) return Problem(Status(result.Code), result.Code, operation); if (etag && result.Value is InventoryCustomerReturnResponse value) SetEtag(http, value.Version); return Results.Ok(result.Value);
    }

    private static async Task<IResult> ExecuteMutationAsync(HttpContext http, ITrustedRequestContextResolver resolver, InventoryTenantContextResolver tenant, string operation, bool needsVersion, Func<InventoryRequestContext, byte[]?, Task<InventoryOperationResult<InventoryCustomerReturnResponse>>> action)
    {
        if (!await Anti(http)) return Problem(403, "antiforgery_failed", operation); var key = Key(http); if (!FoundationCorrelation.IsValid(key)) return Problem(400, "idempotency_key_invalid", operation); var version = needsVersion ? ReadVersion(http) : null; if (needsVersion && version is null) return Problem(400, "version_required", operation); var foundation = await resolver.ResolveAsync(http, http.RequestAborted); var resolved = tenant.Resolve(foundation); if (!resolved.Allowed || resolved.Context is null) return Problem(foundation.SecurityProfile == FoundationSecurityProfile.Anonymous ? 401 : 403, resolved.Code, operation); var result = await action(resolved.Context, version); if (!result.Succeeded || result.Value is null) return Problem(Status(result.Code), result.Code, operation); SetEtag(http, result.Value.Version); return Results.Ok(result.Value);
    }

    private static async Task<IResult> FinanceRead<T>(HttpContext http, ITrustedRequestContextResolver resolver, string operation, Func<FinanceRequestContext, Task<FinanceOperationResult<T>>> action, bool etag = false)
    {
        var foundation = await resolver.ResolveAsync(http, http.RequestAborted); if (!FinanceRequestContext.TryCreate(foundation, out var context) || context is null) return Problem(foundation.SecurityProfile == FoundationSecurityProfile.Anonymous ? 401 : 403, "finance_context_failed", operation); var result = await action(context); if (!result.Succeeded || result.Value is null) return Problem(Status(result.Code), result.Code, operation); if (etag && result.Value is FinanceCreditNoteResponse value) SetEtag(http, value.Version); return Results.Ok(result.Value);
    }

    private static async Task<IResult> ExecuteMutationAsync(HttpContext http, ITrustedRequestContextResolver resolver, string operation, bool needsVersion, Func<FinanceRequestContext, byte[]?, Task<FinanceOperationResult<FinanceCreditNoteResponse>>> action)
    {
        if (!await Anti(http)) return Problem(403, "antiforgery_failed", operation); var key = Key(http); if (!FoundationCorrelation.IsValid(key)) return Problem(400, "idempotency_key_invalid", operation); var version = needsVersion ? ReadVersion(http) : null; if (needsVersion && version is null) return Problem(400, "version_required", operation); var foundation = await resolver.ResolveAsync(http, http.RequestAborted); if (!FinanceRequestContext.TryCreate(foundation, out var context) || context is null) return Problem(foundation.SecurityProfile == FoundationSecurityProfile.Anonymous ? 401 : 403, "finance_context_failed", operation); var result = await action(context, version); if (!result.Succeeded || result.Value is null) return Problem(Status(result.Code), result.Code, operation); SetEtag(http, result.Value.Version); return Results.Ok(result.Value);
    }

    private static FoundationOperationMetadata Metadata(string operation) => new(FoundationOperationCatalog.GetRequired(operation));
    private static string? Key(HttpContext http) => http.Request.Headers["Idempotency-Key"].FirstOrDefault();
    private static byte[]? ReadVersion(HttpContext http) { var value = http.Request.Headers.IfMatch.FirstOrDefault(); if (string.IsNullOrWhiteSpace(value) || value.StartsWith("W/", StringComparison.OrdinalIgnoreCase)) return null; value = value.Trim(); if (value.Length > 1 && value[0] == '"' && value[^1] == '"') value = value[1..^1]; try { var version = Convert.FromBase64String(value); return version.Length is > 0 and <= 64 ? version : null; } catch (FormatException) { return null; } }
    private static void SetEtag(HttpContext http, byte[] version) => http.Response.Headers.ETag = $"\"{Convert.ToBase64String(version)}\"";
    private static async Task<bool> Anti(HttpContext http) { try { await http.RequestServices.GetRequiredService<IAntiforgery>().ValidateRequestAsync(http); return true; } catch (AntiforgeryValidationException) { return false; } }
    private static int Status(string code) => code switch { "permission_denied" => 403, "customer_return_not_found" or "return_source_not_found" or "inventory_customer_return_not_found" or "credit_note_not_found" or "sales_return_not_found" => 404, "concurrency_conflict" or "idempotency_conflict" or "return_quantity_conflict" or "customer_return_transition_invalid" or "sales_return_not_awaiting_receipt" or "inventory_customer_return_transition_invalid" or "disposition_quantity_conflict" or "delivery_cost_evidence_missing" or "credit_note_duplicate" or "credit_note_transition_invalid" or "finance_open_item_unavailable" or "sales_finance_acknowledgement_required" or "sales_finance_reversal_required" => 409, "finance_customer_return_persistence_unavailable" or "inventory_customer_return_persistence_unavailable" or "finance_commit_failed" or "finance_reconciliation_persist_failed" => 503, _ => 400 };
    private static IResult Problem(int status, string code, string operation) => Results.Problem(statusCode: status, title: code, detail: "The customer return operation could not be completed.", extensions: new Dictionary<string, object?> { ["code"] = code, ["operationId"] = operation });
}

#pragma warning restore CS1591
